import pytest
from hypothesis import given
import hypothesis.strategies as st
from solution import compare_one


def _parse(v):
    """Obviously-correct reference parsing per spec: ',' is decimal point."""
    if isinstance(v, str):
        return float(v.replace(",", "."))
    return float(v)


def _expected(a, b):
    na = _parse(a)
    nb = _parse(b)
    if na == nb:
        return None
    return a if na > nb else b


# ---- explicit spec examples ----
def test_example_int_vs_float():
    assert compare_one(1, 2.5) == 2.5
    assert isinstance(compare_one(1, 2.5), float)


def test_example_int_vs_comma_string():
    assert compare_one(1, "2,3") == "2,3"
    assert isinstance(compare_one(1, "2,3"), str)


def test_example_comma_string_vs_int_string():
    assert compare_one("5,1", "6") == "6"


def test_example_equal_int_and_string():
    assert compare_one("1", 1) is None


# ---- comma handling, especially second argument ----
def test_comma_in_second_arg_changes_order():
    # Correct: 10 > 2.3 so must return 10; buggy parses "2,3" as 23.
    assert compare_one(10, "2,3") == 10


def test_comma_in_second_arg_equal_dot():
    # 2.3 == "2,3" so must be None; buggy parses "2,3" as 23.
    assert compare_one(2.3, "2,3") is None
    assert compare_one("2.5", "2,5") is None


def test_comma_in_second_arg_equal_int():
    # "1,0" == 1 numerically
    assert compare_one(1, "1,0") is None
    assert compare_one(1.0, "1,0") is None


def test_comma_decimal_second_arg_smaller():
    # 2.3 < 5 so must return 5 regardless of side
    assert compare_one(5, "2,3") == 5
    assert compare_one("2,3", 5) == 5


def test_negative_comma_strings():
    assert compare_one("-1,5", -1.0) is None
    assert compare_one("-1,5", "-1") == "-1"
    assert compare_one(-10, "-2,3") == "-2,3"


def test_returns_original_type_and_identity():
    a = "2,3"
    b = 1
    r = compare_one(a, b)
    assert r == "2,3"
    assert isinstance(r, str)
    assert r is a
    b2 = 2.5
    a2 = 1
    r2 = compare_one(a2, b2)
    assert r2 == 2.5
    assert isinstance(r2, float)
    assert r2 is b2


# ---- property-based tests vs reference model ----
finite_floats = st.floats(
    min_value=-1000, max_value=1000, allow_nan=False, allow_infinity=False
)
ints = st.integers(min_value=-1000, max_value=1000)

def _decimal_string(draw, use_comma):
    neg = draw(st.booleans())
    ip = draw(st.integers(min_value=0, max_value=1000))
    fp = draw(st.integers(min_value=0, max_value=999))
    # ensure at least one fractional digit; pad to keep it simple
    s = f"{ip}.{fp:03d}"
    if use_comma:
        s = s.replace(".", ",")
    if neg:
        s = "-" + s
    return s

@st.composite
def numeric_values(draw):
    kind = draw(st.integers(min_value=0, max_value=3))
    if kind == 0:
        return draw(ints)
    if kind == 1:
        return draw(finite_floats)
    if kind == 2:
        # dot string
        return _decimal_string(draw, False)
    else:
        # comma string
        return _decimal_string(draw, True)

@st.composite
def numeric_pairs(draw):
    return (draw(numeric_values), draw(numeric_values))


@given(numeric_pairs)
def test_property_matches_reference_model(pair):
    a, b = pair
    got = compare_one(a, b)
    exp = _expected(a, b)
    if exp is None:
        assert got is None
    else:
        assert got is (a if exp is a else b)
        assert type(got) is type(exp)
        assert got == exp


@given(numeric_pairs)
def test_property_symmetry(pair):
    a, b = pair
    r1 = compare_one(a, b)
    r2 = compare_one(b, a)
    if r1 is None:
        assert r2 is None
    else:
        # same winner regardless of order, preserving original object
        assert r1 == r2
        assert (r1 is a or r1 is b)
        assert (r2 is a or r2 is b)


@given(numeric_pairs)
def test_property_result_is_one_of_inputs_or_none(pair):
    a, b = pair
    r = compare_one(a, b)
    assert r is None or r is a or r is b


@given(numeric_pairs)
def test_property_ordering_consistent_with_parse(pair):
    a, b = pair
    na = _parse(a)
    nb = _parse(b)
    r = compare_one(a, b)
    if na == nb:
        assert r is None
    elif na > nb:
        assert r is a
    else:
        assert r is b
